 // Capture practice shortcuts before text fields process Option/Alt characters.
 document.addEventListener('keydown',e=>{
  if(!active||uiScreen!=='practice'||$('enQuickDialog').open||document.querySelector('dialog[open]')||e.isComposing||e.defaultPrevented)return;
  const code=e.code||(/^[a-z]$/i.test(e.key)?'Key'+e.key.toUpperCase():e.key),alt=e.altKey&&!e.ctrlKey&&!e.metaKey;
  const answer=alt&&code==='KeyA'||code==='F8'&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey;
  const playback=alt&&code==='KeyP';if(!answer&&!playback)return;
  e.preventDefault();e.stopPropagation();if(e.repeat)return;if(answer)toggleAnalysis();else play();
 },true);
